  "rcloneRemote.hint": "Nær sambandi við Windows- eða Samba-sameign, eða WebDAV-netþjón á borð við Nextcloud, án þess að tengja neitt við hýsilinn. restic mælir gegn því að geyma geymslusafn á tengdri CIFS-sameign, og þessi leið sleppir tengingunni alveg. Lykilorðið er afhent rclone, sem geymir það á eigin formi, og það er aldrei geymt sem hreinn texti. NFS er ekki í boði hér því hvorki restic né rclone styður það: fyrir NFS skaltu tengja sameignina í Unraid og setja afritunarslóð á hana.",
