  "dbdump.saveHint": "Skrifar afritið sem skrá í valda möppu á þjóninum, í eigu nobody:users svo þú getir opnað hana um netsameignina. Skráin inniheldur allar töflur og lykilorðatætur notenda gagnagrunnsins; geymdu hana þar sem aðeins þú kemst að.",
  "dbdump.saveCancelHint": "Að hætta við stöðvar vistunina og fjarlægir hálfkláruðu skrána.",
  "dbdump.savedTo": "Vistað í {path}",
  "dbdump.import": "Flytja inn í nýjan gagnagrunn",
  "dbdump.importConfirm": "Flytja þetta {engine} {version} afrit inn í {container}? BombVault stöðvar gáminn, færir gagnamöppu hans til hliðar (henni er haldið, engu er eytt), ræsir gáminn með tómri gagnamöppu og flytur afritið inn. Forritin sem nota þennan gagnagrunn sjá stöðu hans frá þeim tíma sem afritið var tekið.",
  "dbdump.importConfirmNoVersion": "Flytja þetta {engine} afrit inn í {container}? BombVault stöðvar gáminn, færir gagnamöppu hans til hliðar (henni er haldið, engu er eytt), ræsir gáminn með tómri gagnamöppu og flytur afritið inn. Forritin sem nota þennan gagnagrunn sjá stöðu hans frá þeim tíma sem afritið var tekið.",
  "dbdump.importNoVersion": "Þetta afrit skráir ekki útgáfu gagnagrunnsins. Innflutningurinn mistekst ef þjónninn getur ekki lesið það.",
  "dbdump.importStops": "one=Á meðan innflutningurinn stendur yfir stöðvar BombVault líka {apps} og ræsir það svo aftur. Ef innflutningurinn mistekst eftir að hann er hafinn verða gömlu gögnin áfram til hliðar og forritið stöðvað.|other=Á meðan innflutningurinn stendur yfir stöðvar BombVault líka þessi forrit: {apps}. Á eftir eru þau ræst aftur. Ef innflutningurinn mistekst eftir að hann er hafinn verða gömlu gögnin áfram til hliðar og forritin stöðvuð.",
  "dbdump.importDone": "Gagnagrunnurinn var fluttur inn.",
