  "recovery.foreignAppdataDestHint": "Hvert appdata gámsins er endurheimt. Skildu eftir autt fyrir sjálfgefið. Gámur sem var afritaður úr safni sem þessi netþjónn hefur ekki (t.d. /mnt/zfs) er endurkortlagður hér svo hann lendi rétt.",
