  "oauth.allowStartHint": "Ef kveikt er á þessu getur biðlarinn líka ræst afritun og hætt við afritanir sem hann ræsti, með sömu takmörkum og lykill. Afritun stöðvar keyrandi gáma þar til henni lýkur. Þú getur breytt þessu seinna á reit hans undir Stillingar, Tengingar, MCP-þjónn.",
